      .instance
      .api
      .crateApiNotesNoteMoveItem(that: this, item: item, toIndex: toIndex);

  Future<void> removeItem({required String item}) =>
      RustLib.instance.api.crateApiNotesNoteRemoveItem(that: this, item: item);

  /// Send whatever typing on this note is waiting to go. What a screen does
  /// as it closes, so that leaving a note is not a second's wait to share it.
  void sendHeldEdits() =>
      RustLib.instance.api.crateApiNotesNoteSendHeldEdits(that: this);

  Future<void> setChecked({required String item, required bool checked}) =>
      RustLib.instance.api.crateApiNotesNoteSetChecked(
        that: this,
        item: item,
        checked: checked,
      );

  Future<void> setItemText({required String item, required String text}) =>
      RustLib.instance.api.crateApiNotesNoteSetItemText(
        that: this,
        item: item,
        text: text,
      );

  /// Switch the note between text and checklist, carrying its content across:
  /// lines become items, or items become lines.
  Future<void> setKind({required NoteKindView kind}) =>
      RustLib.instance.api.crateApiNotesNoteSetKind(that: this, kind: kind);

  Future<void> setTitle({required String title}) =>
      RustLib.instance.api.crateApiNotesNoteSetTitle(that: this, title: title);

  /// End this handle's watchers and let their tasks finish. The note stays
  /// open in the library, because another screen may be showing it.
  Future<void> stopWatching() =>
      RustLib.instance.api.crateApiNotesNoteStopWatching(that: this);

  /// Where this note stands with the relay.
  SyncStatus syncStatus() =>
      RustLib.instance.api.crateApiNotesNoteSyncStatus(that: this);

  NoteView view() => RustLib.instance.api.crateApiNotesNoteView(that: this);

  /// Every view from now on, starting with the current one.
  ///
  /// This is the only way the UI learns anything. A local edit and an edit
  /// arriving from another device both come out here, which is what keeps the
  /// one-device and two-device cases identical.
  Stream<NoteView> watch() =>
      RustLib.instance.api.crateApiNotesNoteWatch(that: this);

  Stream<SyncStatus> watchSync() =>
      RustLib.instance.api.crateApiNotesNoteWatchSync(that: this);
}
